.naxos-theme .price-currency, .naxos-theme .price-unit { color: rgba(255,255,255,0.85) !important; }
.naxos-theme .price-subtitle { color: rgba(196,148,74, 0.5) !important; letter-spacing: 3px !important; }
.naxos-theme .price-ornament { border-color: rgba(196,148,74, 0.35) !important; }
.naxos-theme .price-badge:hover .price-ornament { border-color: #c4944a !important; }

