.naxos-theme .product-actions-buttons { position: relative !important; }
.naxos-theme .product-actions-buttons::before { content: '' !important; position: absolute !important; top: -15px !important; left: 15% !important; right: 15% !important; height: 1px !important; background: linear-gradient(90deg, transparent, rgba(196,148,74, 0.25), transparent) !important; }

/* Responsive */
@media (max-width: 768px) {
    .naxos-product-section { flex-direction: column !important; text-align: center !important; }
    .naxos-image { width: 250px !important; }
    .naxos-profiles-container { flex-direction: row !important; flex-wrap: nowrap !important; overflow-x: auto !important; }
    .naxos-rating-row { flex-direction: column !important; }
}

