.aquadigioelixir-theme .review-textarea { background: rgba(255,255,255,0.04) !important; border-color: rgba(26,107,107,0.2) !important; color: rgba(255,255,255,0.90) !important; }
.aquadigioelixir-theme .submit-btn { background: linear-gradient(135deg, #0a5b5b, #1a6b6b) !important; color: #0a0a0f !important; }

/* Responsive */
@media (max-width: 768px) {
    .aquadigioelixir-product-section { flex-direction: column !important; text-align: center !important; }
    .aquadigioelixir-image { width: 250px !important; }
    .aquadigioelixir-profiles-container { flex-direction: row !important; flex-wrap: nowrap !important; overflow-x: auto !important; }
