.eliesaabinwhite-vote-count { font-size: 0.85rem !important; font-weight: 700 !important; color: rgba(255, 255, 255, 0.90) !important; }
.eliesaabinwhite-subreddit { font-weight: 700 !important; color: rgba(255, 255, 255, 0.90) !important; font-size: 0.85rem !important; }
.eliesaabinwhite-post-dot { color: #FFFFFF !important; margin: 0 5px !important; }
.eliesaabinwhite-post-info, .eliesaabinwhite-post-time { color: rgba(255, 255, 255, 0.55) !important; font-size: 0.75rem !important; }
.eliesaabinwhite-user-avatar img { width: 36px !important; height: 36px !important; border-radius: 50% !important; }
.eliesaabinwhite-reddit-user { display: flex !important; align-items: center !important; gap: 10px !important; margin-bottom: 12px !important; }
.eliesaabinwhite-user-details { display: flex !important; flex-direction: column !important; }
.eliesaabinwhite-username { font-weight: 600 !important; color: rgba(255, 255, 255, 0.90) !important; font-size: 0.85rem !important; }
.eliesaabinwhite-reddit-text p { color: rgba(255, 255, 255, 0.80) !important; line-height: 1.7 !important; font-style: italic !important; }
.eliesaabinwhite-reddit-engagement { display: flex !important; gap: 20px !important; margin-top: 15px !important; padding-top: 12px !important; border-top: 1px solid rgba(232,232,232,0.1) !important; }
.eliesaabinwhite-engagement-item { display: flex !important; align-items: center !important; gap: 5px !important; font-size: 0.8rem !important; color: rgba(255, 255, 255, 0.55) !important; }

/* Mood/Season Indicators */
.eliesaabinwhite-perfume-rating { padding: 30px 0 !important; color: rgba(255, 255, 255, 0.88) !important; }
.eliesaabinwhite-rating-indicators { display: flex !important; gap: 30px !important; flex-wrap: wrap !important; margin-bottom: 25px !important; }
.eliesaabinwhite-mood-indicators, .eliesaabinwhite-seasonal-indicators { display: flex !important; gap: 12px !important; flex-wrap: wrap !important; }
.eliesaabinwhite-indicator-item { display: flex !important; flex-direction: column !important; align-items: center !important; gap: 5px !important; opacity: 0.4 !important; transition: opacity 0.3s ease !important; }
.eliesaabinwhite-indicator-item.active { opacity: 1 !important; }
.eliesaabinwhite-indicator-icon { font-size: 1.3rem !important; }
.eliesaabinwhite-indicator-label { font-size: 0.65rem !important; text-transform: uppercase !important; letter-spacing: 0.5px !important; color: rgba(255, 255, 255, 0.68) !important; }
.eliesaabinwhite-indicator-bar { width: 30px !important; height: 3px !important; background: rgba(232,232,232,0.2) !important; border-radius: 2px !important; }
.eliesaabinwhite-indicator-item.active .eliesaabinwhite-indicator-bar { background: #e8e8e8 !important; }
.eliesaabinwhite-rating-title { font-size: 1rem !important; color: rgba(255, 255, 255, 0.92) !important; font-weight: 400 !important; text-shadow: 0 2px 14px rgba(0, 0, 0, 0.45) !important; }
.eliesaabinwhite-score { font-weight: 700 !important; color: rgba(255, 255, 255, 0.98) !important; font-size: 1.3rem !important; }
.eliesaabinwhite-votes { font-weight: 600 !important; color: #FFFFFF !important; }
.eliesaabinwhite-perfume-description p { color: rgba(255, 255, 255, 0.82) !important; line-height: 1.7 !important; margin-top: 15px !important; }
.eliesaabinwhite-perfume-description strong { color: rgba(255, 255, 255, 0.95) !important; }

/* Favourite & Cart Buttons */
.eliesaabinwhite-theme .favorite-btn { color: rgba(255, 255, 255, 0.90) !important; border: 1px solid rgba(232,232,232, 0.3) !important; background: transparent !important; }
.eliesaabinwhite-theme .favorite-btn:hover { background: rgba(232,232,232, 0.08) !important; border-color: #e8e8e8 !important; color: rgba(255, 255, 255, 0.95) !important; box-shadow: 0 4px 20px rgba(232,232,232, 0.2) !important; }
