.eliesaabinwhite-theme .price-badge:hover .price-ornament { border-color: #e8e8e8 !important; }

/* Card Enhancements */
.eliesaabinwhite-theme .product-actions-buttons { position: relative !important; }
.eliesaabinwhite-theme .product-actions-buttons::before { content: '' !important; position: absolute !important; top: -15px !important; left: 15% !important; right: 15% !important; height: 1px !important; background: linear-gradient(90deg, transparent, rgba(232,232,232, 0.25), transparent) !important; }

/* Responsive */
@media (max-width: 768px) {
