.eliesaabinwhite-theme .submit-btn { background: linear-gradient(135deg, #747474, #e8e8e8) !important; color: #0a0a0f !important; }

/* Responsive */
@media (max-width: 768px) {
    .eliesaabinwhite-product-section { flex-direction: column !important; text-align: center !important; }
